export function toGatheringCborValue(v: Gathering): CborValue {
  const csilMap = new Map<CborValue, CborValue>();
  csilMap.set("id", v.id);
  csilMap.set("name", v.name);
  csilMap.set("slug", v.slug);
  csilMap.set("blurb", v.blurb);
  csilMap.set("origin", toOriginCborValue(v.origin));
  csilMap.set("owners", v.owners.map((csilE): CborValue => toOwnerRefCborValue(csilE)));
  csilMap.set("viewer", toViewerContextCborValue(v.viewer));
  csilMap.set("publish", toPublishDecisionCborValue(v.publish));
  csilMap.set("created_at", { tag: 0, value: csilTsToText(v.createdAt) });
  csilMap.set("updated_at", { tag: 0, value: csilTsToText(v.updatedAt) });
  csilMap.set("description", v.description);
  csilMap.set("event_count", v.eventCount);
  csilMap.set("member_count", v.memberCount);
  if (v.nextEventAt !== undefined) csilMap.set("next_event_at", { tag: 0, value: csilTsToText(v.nextEventAt) });
  csilMap.set("origin_domain", v.originDomain);
  csilMap.set("publish_events", v.publishEvents);
  return csilMap;
}

export function fromGatheringCborValue(value: CborValue): Gathering {
  return {
    id: asString(requireKey(value, "id")),
    slug: asString(requireKey(value, "slug")),
    originDomain: asString(requireKey(value, "origin_domain")),
    name: asString(requireKey(value, "name")),
    blurb: asString(requireKey(value, "blurb")),
    description: asString(requireKey(value, "description")),
    owners: asArray(requireKey(value, "owners")).map((csilE) => fromOwnerRefCborValue(csilE)),
    memberCount: asNumber(requireKey(value, "member_count")),
    eventCount: asNumber(requireKey(value, "event_count")),
    nextEventAt: ((csilV: CborValue | undefined) => csilV === undefined ? undefined : asTimestamp(csilV))(mapGet(value, "next_event_at")),
    publishEvents: (asEnumMember(asString(requireKey(value, "publish_events")), ["unset", "in", "out"]) as "unset" | "in" | "out"),
    publish: fromPublishDecisionCborValue(requireKey(value, "publish")),
    origin: fromOriginCborValue(requireKey(value, "origin")),
    viewer: fromViewerContextCborValue(requireKey(value, "viewer")),
    createdAt: asTimestamp(requireKey(value, "created_at")),
    updatedAt: asTimestamp(requireKey(value, "updated_at")),
  };
}

